(() => {
  'use strict';
  const target=new Date('2027-01-09T00:00:00+05:30').getTime();
  function updateCountdown(){const total=Math.max(0,Math.floor((target-Date.now())/1000));const values=[Math.floor(total/86400),Math.floor(total/3600)%24,Math.floor(total/60)%60,total%60];['days','hours','minutes','seconds'].forEach((id,i)=>document.getElementById(id).textContent=String(values[i]).padStart(2,'0'));if(Date.now()>=target)document.querySelector('.countdown-top > span').textContent='THE WAIT IS OVER';}
  updateCountdown();setInterval(updateCountdown,1000);
  let toastTimer;window.showToast=message=>{const el=document.getElementById('notice');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),5500);};
  document.getElementById('calendar').addEventListener('click',()=>{const text=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Graffiti SCIT//Graffiti 2027//EN','CALSCALE:GREGORIAN','BEGIN:VEVENT','UID:graffiti-2027-20270109@scit.edu','DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,''),'DTSTART;VALUE=DATE:20270109','DTEND;VALUE=DATE:20270110','SUMMARY:Graffiti 2027','DESCRIPTION:Graffiti 2027 at SCIT. Theme and team reveal coming soon.','LOCATION:SCIT\\, Pune','END:VEVENT','END:VCALENDAR'].join('\r\n')+'\r\n';const url=URL.createObjectURL(new Blob([text],{type:'text/calendar;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='graffiti-2027.ics';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);window.showToast('Date saved. Open the downloaded file in your calendar.');});
  const media=matchMedia('(prefers-reduced-motion: reduce)');window.worldPaused=media.matches;
  const updateMotion=()=>{document.body.classList.toggle('motion-paused',window.worldPaused);window.dispatchEvent(new Event('world-motion'));};
  media.addEventListener('change',e=>{window.worldPaused=e.matches;updateMotion();});updateMotion();
  const dialog=document.getElementById('secret-dialog');document.querySelectorAll('[data-secret]').forEach(button=>button.addEventListener('click',()=>{const theme=button.dataset.secret==='theme';document.getElementById('secret-title').innerHTML=theme?'A new expression.<br>Still under wraps.':'New minds.<br>Same wild spirit.';document.getElementById('secret-copy').textContent=theme?'The Graffiti 2027 theme is still a secret. This sculpture is teaser art — the official theme reveal is coming soon.':'A new team is leaving its mark on Graffiti 2027. Names and faces will be revealed soon. Keep 9 January 2027 free.';dialog.showModal();}));document.querySelectorAll('.dialog-close,.dialog-done').forEach(button=>button.addEventListener('click',()=>dialog.close()));dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
})();
